presets.css:
/* ===== 由「气泡生成器」导出 · 贴到对话主题 A 区 ===== */
.chat-thread {
  /* 顶栏胶囊 */
  --dress-header-bg: rgba(255, 235, 148, 0.830);
  --dress-header-blur: 7px;
  --dress-header-border: rgba(0, 0, 0, 0.260);
  --dress-header-radius: 0px;
  --dress-header-shadow: 0 3px 9px rgba(0, 0, 0, 0.031);
  --dress-header-title-color: #1a1a1a;
  --dress-header-title-size: 15px;
  --dress-header-title-weight: 500;
  --dress-header-icon-color: #ffe587;

  /* 我方气泡 */
  --dress-bubble-me-bg: #fff3cf;
  --dress-bubble-me-fg: #000000;
  --dress-bubble-me-border: 1px solid #000000;
  --dress-bubble-me-shadow: 0 2px 11px rgba(0, 0, 0, 0.075);
  --dress-bubble-me-radius: 12px;

  /* 对方气泡 */
  --dress-bubble-them-bg: #fff1ab;
  --dress-bubble-them-fg: #1a1a1a;
  --dress-bubble-them-border: 0.5px solid #000000;
  --dress-bubble-them-shadow: 0 2px 11px rgba(0, 0, 0, 0.075);
  --dress-bubble-them-radius: 12px;

  /* 输入胶囊 */
  --dress-compose-bar-bg: rgba(255, 234, 176, 0.920);
  --dress-compose-bar-fg: #1a1a1a;
  --dress-compose-bar-radius: 0px;
  --dress-compose-bar-border: 1px solid rgba(255, 255, 255, 0.350);
  --dress-compose-bar-shadow: 0 3px 11px rgba(0, 0, 0, 0.035);
  --dress-compose-bar-blur: blur(18px);

  /* 其他 */
  --dress-timestamp-color: #9aa2b2;
}
